                                                                (96, 'Triumph of the Hordes', 'New Phyrexia', 'SORCERY', 'Uncommon', '{2}{G}{G}', 'G', NULL, NULL, 'Indtil slutningen af turen får creatures du kontrollerer +1/+1 og trample og infect.'),
                                                                (97, 'Ruinous Ultimatum', 'Ikoria: Lair of Behemoths', 'SORCERY', 'Rare', '{W}{W}{B}{B}{B}{R}{R}', 'W,B,R', NULL, NULL, 'Ødelæg alle nonland permanenter dine modstandere kontrollerer.'),
