                                                                (99, 'Liliana of the Veil', 'Innistrad', 'PLANESWALKER', 'MythicRare', '{1}{B}{B}', 'B', NULL, NULL, '+1: Hver spiller discarder et kort. -2: Target spiller ofrer en creature. -6: Adskil alle permanenter target spiller kontrollerer i to bunker. Spilleren ofrer alle permanenter i den ene bunke.'),
                                                                (100, 'Chandra, Torch of Defiance', 'Kaladesh', 'PLANESWALKER', 'MythicRare', '{2}{R}{R}', 'R', NULL, NULL, '+1: Exil det øverste kort af dit bibliotek. Du må kaste det kort. Hvis du ikke gør, gør Chandra 2 skade på hver modstander. +1: Tilføj {R}{R}. -3: Chandra gør 4 skade på target creature. -7: Du får en emblem med "Når du kaster en spell, gør denne emblem 5 skade på target creature eller spiller."'),
                                                                (101, 'Teferi, Time Raveler', 'War of the Spark', 'PLANESWALKER', 'Rare', '{1}{W}{U}', 'W,U', NULL, NULL, 'Hver modstander kan kun kaste spells når de kunne kaste en sorcery. +1: Indtil din næste tur, kan du kaste sorcery spells som om de havde flash. -3: Returner target artifact, creature eller enchantment til dens ejers hånd. Træk et kort.'),
                                                                (102, 'Wrenn and Six', 'Modern Horizons', 'PLANESWALKER', 'MythicRare', '{R}{G}', 'R,G', NULL, NULL, '+1: Returner target land kort fra din graveyard til din hånd. -1: Wrenn and Six gør 1 skade på target. -7: Du får en emblem med "Instant og sorcery kort i din graveyard har retrace."'),
                                                                (103, 'Birds of Paradise', 'Alpha', 'CREATURE', 'Rare', '{G}', 'G', '0', '1', 'Flying. {T}: Tilføj en mana af en hvilken som helst farve.'),
                                                                (104, 'Tarmogoyf', 'Future Sight', 'CREATURE', 'MythicRare', '{1}{G}', 'G', '0', '1', 'Tarmogoyfs power er lig med antallet af korttyper blandt kort i alle graveyards, og dens toughness er lig med det tal plus 1.'),
                                                                (105, 'Snapcaster Mage', 'Innistrad', 'CREATURE', 'Rare', '{1}{U}', 'U', '2', '1', 'Flash. Når Snapcaster Mage kommer i spil, får target instant eller sorcery kort i din graveyard flashback indtil slutningen af turen lig med dets mana cost.'),
                                                                (106, 'Dark Confidant', 'Ravnica: City of Guilds', 'CREATURE', 'Rare', '{1}{B}', 'B', '2', '1', 'I starten af din upkeep, afslør det øverste kort af dit bibliotek og læg det i din hånd. Du mister liv lig med dets mana value.'),
                                                                (107, 'Stoneforge Mystic', 'Worldwake', 'CREATURE', 'Rare', '{1}{W}', 'W', '1', '2', 'Når Stoneforge Mystic kommer i spil, må du søge i dit bibliotek efter et Equipment kort, afsløre det og lægge det i din hånd. {1}{W}, {T}: Du må lægge et Equipment kort fra din hånd i spil.'),
                                                                (108, 'Thalia, Guardian of Thraben', 'Dark Ascension', 'CREATURE', 'Rare', '{1}{W}', 'W', '2', '1', 'First strike. Noncreature spells koster {1} mere at kaste.'),
                                                                (109, 'Goblin Guide', 'Zendikar', 'CREATURE', 'Rare', '{R}', 'R', '2', '2', 'Haste. Når Goblin Guide angriber, afslører forsvarende spiller det øverste kort af sit bibliotek. Hvis det er et land, lægger spilleren det i sin hånd.'),
                                                                (110, 'Noble Hierarch', 'Conflux', 'CREATURE', 'Rare', '{G}', 'G,W,U', '0', '1', 'Exalted. {T}: Tilføj {G}, {W} eller {U}.'),
                                                                (111, 'Bloodbraid Elf', 'Alara Reborn', 'CREATURE', 'Uncommon', '{2}{R}{G}', 'R,G', '3', '2', 'Haste, cascade.'),
                                                                (112, 'Scavenging Ooze', 'Commander 2011', 'CREATURE', 'Rare', '{1}{G}', 'G', '2', '2', '{G}: Exil target kort fra en graveyard. Hvis det var et creature kort, læg en +1/+1 counter på Scavenging Ooze, og du får 1 liv.'),
                                                                (113, 'Deathrite Shaman', 'Return to Ravnica', 'CREATURE', 'Rare', '{B/G}', 'B,G', '1', '2', '{T}: Exil target land fra en graveyard. Tilføj en mana af en hvilken som helst farve. {B}, {T}: Exil target instant eller sorcery fra en graveyard. Hver modstander mister 2 liv. {G}, {T}: Exil target creature fra en graveyard. Du får 2 liv.'),
                                                                (114, 'Monastery Swiftspear', 'Khans of Tarkir', 'CREATURE', 'Uncommon', '{R}', 'R', '1', '2', 'Haste, prowess.'),
                                                                (115, 'Delver of Secrets', 'Innistrad', 'CREATURE', 'Common', '{U}', 'U', '1', '1', 'I starten af din upkeep, kig på det øverste kort af dit bibliotek. Du må afsløre det. Hvis et instant eller sorcery kort afsløres på denne måde, transformer Delver of Secrets.'),
                                                                (116, 'Llanowar Elves', 'Alpha', 'CREATURE', 'Common', '{G}', 'G', '1', '1', '{T}: Tilføj {G}.'),
                                                                (117, 'Baleful Strix', 'Planechase 2012', 'CREATURE', 'Uncommon', '{U}{B}', 'U,B', '1', '1', 'Flying, deathtouch. Når Baleful Strix kommer i spil, træk et kort.'),
                                                                (118, 'Uro, Titan of Nature''s Wrath', 'Theros Beyond Death', 'CREATURE', 'MythicRare', '{1}{G}{U}', 'G,U', '6', '6', 'Når Uro kommer i spil, ofr ham medmindre han escapede. Når Uro kommer i spil eller angriber, får du 3 liv og trækker et kort, og du må lægge et land kort fra din hånd i spil.'),
                                                                (119, 'Kroxa, Titan of Death''s Hunger', 'Theros Beyond Death', 'CREATURE', 'MythicRare', '{B}{R}', 'B,R', '6', '6', 'Når Kroxa kommer i spil, ofr ham medmindre han escapede. Når Kroxa kommer i spil eller angriber, discarder hver modstander et kort, derefter mister hver modstander der ikke discardede et nonland kort 3 liv.'),
                                                                (120, 'Primeval Titan', 'Magic 2011', 'CREATURE', 'MythicRare', '{4}{G}{G}', 'G', '6', '6', 'Trample. Når Primeval Titan kommer i spil eller angriber, må du søge i dit bibliotek efter op til to land kort, lægge dem i spil tapped og derefter blande.'),
                                                                (121, 'Griselbrand', 'Avacyn Restored', 'CREATURE', 'MythicRare', '{4}{B}{B}{B}{B}', 'B', '7', '7', 'Flying, lifelink. Betal 7 liv: Træk syv kort.'),
                                                                (122, 'Emrakul, the Aeons Torn', 'Rise of the Eldrazi', 'CREATURE', 'MythicRare', '{15}', 'C', '15', '15', 'Denne spell kan ikke blive countered. Når du kaster denne spell, tag en ekstra tur. Flying, protection from colored spells, annihilator 6. Når Emrakul puttes i en graveyard, blander ejeren sin graveyard ind i sit bibliotek.'),
                                                                (123, 'Craterhoof Behemoth', 'Avacyn Restored', 'CREATURE', 'MythicRare', '{6}{G}{G}', 'G', '5', '5', 'Haste. Når Craterhoof Behemoth kommer i spil, får creatures du kontrollerer trample og +X/+X indtil slutningen af turen, hvor X er antallet af creatures du kontrollerer.'),
                                                                (124, 'Elesh Norn, Grand Cenobite', 'New Phyrexia', 'CREATURE', 'MythicRare', '{5}{W}{W}', 'W', '4', '7', 'Vigilance. Andre creatures du kontrollerer får +2/+2. Creatures dine modstandere kontrollerer får -2/-2.'),
                                                                (125, 'Sheoldred, the Apocalypse', 'Dominaria United', 'CREATURE', 'MythicRare', '{2}{B}{B}', 'B', '4', '5', 'Deathtouch. Når du trækker et kort, får du 2 liv. Når en modstander trækker et kort, mister de 2 liv.'),
                                                                (126, 'Thassa''s Oracle', 'Theros Beyond Death', 'CREATURE', 'Rare', '{U}{U}', 'U', '1', '3', 'Når Thassa''s Oracle kommer i spil, kig på de øverste X kort af dit bibliotek, hvor X er din devotion to blue. Læg op til ét af dem på toppen og resten på bunden. Hvis X er større end eller lig med antallet af kort i dit bibliotek, vinder du spillet.'),
                                                                (127, 'Dockside Extortionist', 'Commander 2019', 'CREATURE', 'Rare', '{1}{R}', 'R', '1', '2', 'Når Dockside Extortionist kommer i spil, skab X Treasure tokens, hvor X er antallet af artifacts og enchantments dine modstandere kontrollerer.'),
                                                                (128, 'Ragavan, Nimble Pilferer', 'Modern Horizons 2', 'CREATURE', 'MythicRare', '{R}', 'R', '2', '1', 'Når Ragavan gør combat damage til en spiller, skab en Treasure token og exil det øverste kort af den spillers bibliotek. Indtil slutningen af turen må du kaste det kort. Dash {1}{R}.'),
                                                                (129, 'Esper Sentinel', 'Modern Horizons 2', 'CREATURE', 'Rare', '{W}', 'W', '1', '1', 'Når en modstander kaster deres første noncreature spell hver tur, må du trække et kort, medmindre den spiller betaler {X}, hvor X er Esper Sentinels power.'),
                                                                (130, 'Urza, Lord High Artificer', 'Modern Horizons', 'CREATURE', 'MythicRare', '{2}{U}{U}', 'U', '1', '4', 'Når Urza kommer i spil, skab en 0/0 colorless Construct artifact creature token med "Denne creature får +1/+1 for hvert artifact du kontrollerer." Tap et untappet artifact du kontrollerer: Tilføj {U}. {5}: Exil det øverste kort af dit bibliotek. Indtil slutningen af turen må du spille det.'),
                                                                (131, 'Yawgmoth, Thran Physician', 'Modern Horizons', 'CREATURE', 'MythicRare', '{2}{B}{B}', 'B', '2', '4', 'Protection fra Humans. Betal 1 liv, Ofr et andet creature: Læg en -1/-1 counter på op til et target creature og træk et kort. {B}{B}, Discard et kort: Proliferate.'),
                                                                (132, 'Avenger of Zendikar', 'Worldwake', 'CREATURE', 'MythicRare', '{5}{G}{G}', 'G', '5', '5', 'Når Avenger of Zendikar kommer i spil, skab en 0/1 grøn Plant creature token for hvert land du kontrollerer. Landfall — Når et land kommer i spil under din kontrol, læg en +1/+1 counter på hver Plant du kontrollerer.');
